INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('v_w_mix', '{"hindi_belt": 0.4, "bengali_odia_belt": 0.7}', 'v/w merger most consistently attributed to Bengali/Odia/Assamese L1 phonology; secondary association with Bhojpuri/Bihari speakers. Most discriminative bucket in the set. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('vowel_shift', '{"hindi_belt": 0.4, "dravidian_belt": 0.5, "generic_indian_english": 0.3}', 'Bucket conflates two distinct patterns: word-initial epenthesis before consonant clusters (school->iskool, more Dravidian/Hindi-belt) and general vowel quality shift (pan-Indian). Treated as moderate discriminator pending split. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('retroflex_td', '{"hindi_belt": 0.3, "dravidian_belt": 0.3, "generic_indian_english": 0.7}', 'Retroflex consonants are NATIVE phonemes across nearly all major Indian language families (Indo-Aryan and Dravidian) - substitution for English alveolar stops is closer to pan-Indian-English than regionally discriminative. Low specificity intentional. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('th_sound', '{"generic_indian_english": 0.8}', 'Dental-fricative-to-stop substitution is near-universal across Indian English regardless of L1. Not regionally discriminative - included for MTI-presence signal only, excluded from region attribution weighting. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('wrong_stress', '{"generic_indian_english": 0.7}', 'Syllable-timed vs stress-timed rhythm is a pan-Indian English feature, not regionally discriminative on its own. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('syllabic_schwa', '{"generic_indian_english": 0.7}', 'Schwa deletion/insertion pattern, pan-Indian rhythmic feature. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('dropped_sounds', '{"dravidian_belt": 0.4, "bengali_odia_belt": 0.3, "generic_indian_english": 0.3}', 'Consonant cluster simplification - variably associated with Dravidian and Bengali/Odia cluster-breaking patterns. Weak discriminator. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('extra_sound', '{"dravidian_belt": 0.4, "bengali_odia_belt": 0.3, "generic_indian_english": 0.3}', 'Consonant cluster epenthesis - mirrors dropped_sounds rationale. Weak discriminator. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('ending_markers', '{"generic_indian_english": 0.6}', 'Bucket semantics under-specified from current word_bank data - treated conservatively as low-specificity pan-Indian marker pending clarification. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
INSERT INTO public.bucket_l1_mapping (bucket, region_weights, source_notes, reviewed_by_slp, created_at, updated_at) VALUES ('looks_different', '{"generic_indian_english": 0.6}', 'Bucket semantics under-specified (grapheme-phoneme mismatch class) - treated conservatively as low-specificity pan-Indian marker. UNREVIEWED.', false, '2026-09-14 13:36:59.677105+00', '2026-09-14 13:36:59.677105+00') ON CONFLICT DO NOTHING;
